import { Component, DestroyRef, ElementRef, OnInit, QueryList, signal, ViewChild, viewChild, viewChildren, ViewChildren } from '@angular/core';
import { DevotionalEventPlanner } from '../../services/devotional-event-planner';
import { TextToSpeechService } from '../../../utils/services/text-to-speech/text-to-speech-service';
import { SpeechRecognitionService } from '../../../utils/services/speech-recogniton/speech-recognition-service';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, Validators, ValueChangeEvent } from '@angular/forms';
import { filter } from 'rxjs';
import { CustomCheckbox } from '../../../utils/components/custom-checkbox/custom-checkbox';

@Component({
  selector: 'devotional-current-event',
  standalone: false,
  templateUrl: './devotional-current-event.html',
  styleUrl: './devotional-current-event.css',
})
export class DevotionalCurrentEvent implements OnInit {

  isLoading = signal(false);
  isLanguageSelected = signal(false);
  isBasicInfoExpanded = signal(false);
  isHowToCelebrateExpanded = signal(false);
  isAIPanditExpanded = signal(false);
  setCheckBoxState = signal({id:'', enabled:true});
  isSpeaking = signal('');
  isListining = signal('');

  selectedLang = signal({ id: 2, value: "Hindi" });

  scheduledEvents: any;
  firstToBeLoaded: any;
  loadedAiPunditData = signal<any>({});
  inputRef = viewChild<ElementRef<HTMLInputElement>>('audioInput');
  checkBoxRef = viewChild<ElementRef<HTMLInputElement>>('checkboxInput');

  //elementRef = viewChild<ElementRef<HTMLInputElement>>('checkboxInput');


  userSankalpForm!: FormGroup;
  userSankalpConfirmation: string = '';
  userSankalp: string = '';


  constructor(
    private readonly _eventService: DevotionalEventPlanner,
    private readonly _textToSpeechService: TextToSpeechService,
    private readonly _speechService: SpeechRecognitionService,
    private readonly _destroyRef: DestroyRef
  ) {

    this.initUserSankalpForm();

    this.handleSankalpValueChange();

    this._speechService.getTranscript().pipe(takeUntilDestroyed(this._destroyRef)).subscribe(
      (transcript) => {
        if (transcript.id === this.isListining()) {
          const elementRef = this.inputRef();
          if (elementRef && elementRef.nativeElement.id === transcript.id) {
            elementRef.nativeElement.value += ' ' + transcript.text;
          }
        }
        this.isListining.set('');
      }
    );
  }

  ngOnInit(): void {
    this.isLoading.set(true);
    this._eventService.getScheduledEvents().subscribe(d => {
      this.scheduledEvents = d;//(d as Array<any>).map(e => this.addAdditionalKeys(e))
      //this.scheduledEvents.sort((a: any, b: any) => a.remaining < b.remaining);
      this.firstToBeLoaded = (this.scheduledEvents as Array<any>).find(f => !f.finished);
      this._eventService.getAiPanditData(this.firstToBeLoaded.file).subscribe(d => {
        //console.log(d)
        this.loadedAiPunditData.set(d);
        this.languageChangeHandler((d.language[1] as { id: number, value: string }).id);
        this.userSankalpConfirmation = this.loadedAiPunditData()[this.selectedLang()?.id].aipandit.item.find((item: any) => item.id === 2).aitask;
        this.userSankalp = this.loadedAiPunditData()[this.selectedLang()?.id].aipandit.item.find((item: any) => item.id === 3).aitask;
        this.isLoading.set(false);
      })
    })
  }

  toggleBasicInfo() {
    this.isBasicInfoExpanded.set(!this.isBasicInfoExpanded());
  }

  toggleHowToCelebrate() {
    this.isHowToCelebrateExpanded.set(!this.isHowToCelebrateExpanded());
  }

  toggleAIPandit() {
    this.isAIPanditExpanded.set(!this.isAIPanditExpanded());
  }

  languageChangeHandler(id: number) {
    this.selectedLang.update(() => this.loadedAiPunditData().language.find((d: any) => d.id === id));
    //console.log(this.selectedLang())
  }

  handleTextToSpeech(id: string, text: string, type: string = '', skipSate: boolean = false) { 
    
    this.toggleCheckboxState(id, false);
    this._textToSpeechService.speakTask(text, this.selectedLang().id === 1 ? 'hi-IN' : 'hi-IN', 1.0, 1.0).then(() => {
      if(!skipSate)this.isSpeaking.set('');      
      this.handleSpeechToText('input_text_' + id);
    });

    if(!skipSate)this.isSpeaking.set(id);


   /* const elementRef = this.checkBoxRef();
    console.log('ElementRef:', elementRef, elementRef?.nativeElement.id, this.setCheckBoxDisabled());*/
    
    /*const elementRef = this.checkBoxRef();
    setTimeout(() => {
      console.log('ElementRef:', elementRef, elementRef?.nativeElement.id);
    }, 2000)*/

  }

  handleSpeechToText(id: string) {
    this._speechService.start(id);
    this.isListining.set(id);
  }

  canSpeakChangeHandler(id: string, text: string = '') {
    //console.log('Can speak changed:', event);
    this._textToSpeechService.toggle();
    this.toggleCheckboxState(id, !this.setCheckBoxState().enabled);
    if(!this.setCheckBoxState().enabled) {
      this.handleTextToSpeech(id, text, '', true);
    }
  }

  private toggleCheckboxState(id:string, enabled: boolean){
    this.setCheckBoxState.update((v)=> {
      const update = {...v}
      update.id = id;
      update.enabled = enabled;
      return update;
    } );
  }

  private initUserSankalpForm() {
    this.userSankalpForm = new FormGroup({
      country: new FormControl('', Validators.required),
      state: new FormControl('', Validators.required),
      city: new FormControl('', [Validators.email, Validators.required]),
      village: new FormControl('', [Validators.required, Validators.minLength(10)]),
      direction: new FormControl('', Validators.required),
      gotra: new FormControl('', Validators.required),
      name: new FormControl('', Validators.required),
      othernames: new FormControl('', Validators.required),
      amount: new FormControl('', Validators.required)
    });
  }



  private handleSankalpValueChange() {
    this.userSankalpForm.events
      .pipe(filter(event => event instanceof ValueChangeEvent))
      .subscribe(event => {
        let userSankalpConfirmation: string = this.userSankalpConfirmation;//this.loadedAiPunditData()[this.selectedLang()?.id]?.aipandit.item.find((item: any) => item.id === 2).aitask;
        let userSankalp: string = this.userSankalp;//this.loadedAiPunditData()[this.selectedLang()?.id]?.aipandit.item.find((item: any) => item.id === 3).aitask;
        userSankalpConfirmation = userSankalpConfirmation.replace('#COUNTRY#', this.userSankalpForm.get('country')?.value || 'Bharat')
          .replace('#STATE#', this.userSankalpForm.get('state')?.value || 'Uttar Pradesh')
          .replace('#CITY#', this.userSankalpForm.get('city')?.value || 'Ballia')
          .replace('#VILLAGE#', this.userSankalpForm.get('village')?.value || 'Bhrigu Ashram')
          .replace('#DIRECTION#', this.userSankalpForm.get('direction')?.value || 'Madhya')
          .replace('#GOTRA#', this.userSankalpForm.get('gotra')?.value || 'Gotra')
          .replace('#NAME#', this.userSankalpForm.get('name')?.value || 'Kavindra')
          .replace('#OTHERNAMES#', this.userSankalpForm.get('othernames')?.value || '')
          .replace('#AMOUNT#', this.userSankalpForm.get('amount')?.value || '');
        userSankalp = userSankalp.replace('#COUNTRY#', this.userSankalpForm.get('country')?.value || 'Bharat')
          .replace('#STATE#', this.userSankalpForm.get('state')?.value || 'Uttar Pradesh')
          .replace('#CITY#', this.userSankalpForm.get('city')?.value || 'Ballia')
          .replace('#VILLAGE#', this.userSankalpForm.get('village')?.value || 'Bhrigu Ashram')
          .replace('#DIRECTION#', this.userSankalpForm.get('direction')?.value || 'Madhya')
          .replace('#GOTRA#', this.userSankalpForm.get('gotra')?.value || 'Gotra')
          .replace('#NAME#', this.userSankalpForm.get('name')?.value || 'Kavindra')
          .replace('#OTHERNAMES#', this.userSankalpForm.get('othernames')?.value || '')
          .replace('#AMOUNT#', this.userSankalpForm.get('amount')?.value || '');
        //console.log('Value changed in control:', event.source === this.userSankalpForm.get('country')); // The control that triggered it
        //console.log('New form values:', event.value);

        this.loadedAiPunditData.update((d: any) => {
          const updatedData = { ...d };
          const inputTask = updatedData[this.selectedLang().id]?.aipandit.item.find((item: any) => item.id === 2);
          const finalTask = updatedData[this.selectedLang().id]?.aipandit.item.find((item: any) => item.id === 3);
          if (inputTask) {
            inputTask.aitask = userSankalpConfirmation;
          }
          if (finalTask) {
            finalTask.aitask = userSankalp;
          }
          //console.log('Updated AI Pandit Data:', updatedData);
          return updatedData;
        });
      });
  }



}
