import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { DevotionalEventMain } from './devotional-event-main/devotional-event-main';
import { DevotionalCurrentEvent } from './devotional-current-event/devotional-current-event';

const routes: Routes = [
  {
    path: "", component: DevotionalEventMain, children: [
      { path: '', redirectTo: 'ai-pandit', pathMatch: 'full' },//temp
      { path: "ai-pandit", component: DevotionalCurrentEvent },
      { path: "upcoming", loadChildren: () => import('./devotional-event-planner/devotional-event-planner-module').then((m) => m.DevotionalEventPlannerModule) }
    ]
  },

];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class DevotionalEventRoutingModule { }
